    /**
     * Update proposal status (state machine enforced)
     *
     * Allowed transitions:
     * - `proposed` → `arbiter_review` | `rejected`
     * - `arbiter_review` → `voting` | `rejected`
     * - `voting` → `sandbox_testing` | `rejected`
     * - `sandbox_testing` → `approved` | `rejected`
     * - `approved` → `applied`
     *
     * Any other transition returns 400. Requires admin/founder role.
     *
     * `PUT /api/v1/governance/improvement/{agentId}/{version}/status`
     */
    public suspend fun updateImprovementStatus(agentId: String, version: String, body: UpdateImprovementStatusRequest, options: RequestOptions = RequestOptions()): JsonObject {
        return client.request<JsonObject>(
            RequestSpec(
                method = "PUT",
                path = "/api/v1/governance/improvement/${encodePathSegment(agentId)}/${encodePathSegment(version)}/status",
                body = Body.Json(uarpJson.encodeToString(body)),
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Verify ledger integrity
     *
     * `GET /api/v1/governance/ledger/verify`
     */
    public suspend fun verifyGovernanceLedger(from: String? = null, to: String? = null, options: RequestOptions = RequestOptions()): LedgerIntegrity {
        val query = buildList {
            if (from != null) add("from" to from)
            if (to != null) add("to" to to)
        }
        return client.request<LedgerIntegrity>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/governance/ledger/verify",
                query = query,
                options = options,
            )
        )
    }

